/usr/bin/bash -lc "python3 - <<'PY'
import csv,re
for path in ['data/inputs/sgps_peptide_report/SGPS_peptide-report.tabular','data/inputs/maxquant_peptide_report/MaxQuant-peptide-report.tabular']:
    n=0; micro=0; examples=[]
    with open(path,newline='') as f:
        rd=csv.DictReader(f,delimiter='\\t')
        for row in rd:
            n+=1
            seq=row.get('Sequence','')
            prots=row.get('Proteins') or row.get('Protein(s)') or ''
            if '_9' in prots or (prots.startswith('tr|') and '_HUMAN' not in prots):
                micro+=1
                if len(examples)<10: examples.append((seq,prots))
    print('\\n',path,'rows',n,'micro_guess',micro)
    for e in examples: print(e)
PY"

